// now，不是 to。
//
// market_code 支援空字串 bypass（同 ObservedPriceByGroup），對應 proto
// GetObservedPriceRequest.market_code 的「Omitted = all markets」語意——
// review Finding I2（2026-07-31）：先前這裡是裸的 `=` 比對，crop_code 專屬
// 查詢在 market_code 留空時會回 0 列。DISTINCT ON 鍵一併加回 m.market_code
// （原本只有 po.trade_date）：bypass 後同一 trade_date 可能同時有多個市場
// 的觀測，若不把 market_code 放進 DISTINCT ON，會被併成一列、由哪個市場
// 勝出未定義——與 GroupObservationsAsOf 的 DISTINCT ON 鍵必須含
// market_code 是同一個道理（見該查詢註解、forecast.sql review Finding 1，
// 2026-07-30）。crop_code 本身在這支查詢是固定值（不 bypass），故不需要
// 進 DISTINCT ON 鍵。
//
// source/source_digest/available_at/revision_no（issue #2249 Slice A
// dataMeta 前置，2026-08-07 加）：GetObservedPrice 的 dataMeta 需要這四欄
// 才能算 datasetDigest（Rule 3 跨列政策）與 freshnessStatus（MAX
// available_at 餵 forecast.FreshnessConfig.Classify）——與 avg/upper/
// middle/lower 四個價格欄位同一批新增，理由相同：這支查詢是 dataMeta 唯一
// 能取得「實際回傳列」真身分的地方，晚一步在 usecase 層另外查會跟 Snapshot
// 一致性規則（dataMeta 必須描述同一份 payload）衝突。
func (q *Queries) ObservedPriceByCrop(ctx context.Context, arg ObservedPriceByCropParams) ([]ObservedPriceByCropRow, error) {
	rows, err := q.db.Query(ctx, observedPriceByCrop,
		arg.MarketCode,
		arg.CropCode,
		arg.FromDate,
		arg.ToDate,
		arg.Cutoff,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ObservedPriceByCropRow{}
	for rows.Next() {
		var i ObservedPriceByCropRow
		if err := rows.Scan(
			&i.MarketCode,
			&i.CropCode,
			&i.CategoryCode,
			&i.TradeDate,
			&i.AvgPrice,
			&i.UpperPrice,
			&i.MiddlePrice,
			&i.LowerPrice,
			&i.VolumeKg,
			&i.Source,
			&i.SourceDigest,
			&i.AvailableAt,
			&i.RevisionNo,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const observedPriceByGroup = `-- name: ObservedPriceByGroup :many
SELECT DISTINCT ON (m.market_code, c.crop_code, po.trade_date)
    m.market_code,
    c.crop_code,
    c.category_code,
    po.trade_date,
    po.avg_price,
    po.upper_price,
    po.middle_price,
    po.lower_price,
    po.volume_kg,
    po.source,
    po.source_digest,
    po.available_at,
    po.revision_no
FROM price_observation po
JOIN market m ON m.id = po.market_id
JOIN crop c ON c.id = po.crop_id
JOIN crop_group g ON g.id = c.group_id
WHERE g.group_code = $1
  AND ($2::text = '' OR m.market_code = $2::text)
  AND po.trade_date BETWEEN $3 AND $4
  AND po.available_at <= $5
ORDER BY m.market_code, c.crop_code, po.trade_date, po.revision_no DESC
`

type ObservedPriceByGroupParams struct {
	GroupCode  string             `db:"group_code" json:"group_code"`
	MarketCode string             `db:"market_code" json:"market_code"`
	FromDate   pgtype.Date        `db:"from_date" json:"from_date"`
	ToDate     pgtype.Date        `db:"to_date" json:"to_date"`
	Cutoff     pgtype.Timestamptz `db:"cutoff" json:"cutoff"`
}

type ObservedPriceByGroupRow struct {
	MarketCode   string             `db:"market_code" json:"market_code"`
	CropCode     string             `db:"crop_code" json:"crop_code"`
	CategoryCode *string            `db:"category_code" json:"category_code"`
	TradeDate    pgtype.Date        `db:"trade_date" json:"trade_date"`
	AvgPrice     pgtype.Numeric     `db:"avg_price" json:"avg_price"`
	UpperPrice   pgtype.Numeric     `db:"upper_price" json:"upper_price"`
	MiddlePrice  pgtype.Numeric     `db:"middle_price" json:"middle_price"`
	LowerPrice   pgtype.Numeric     `db:"lower_price" json:"lower_price"`
	VolumeKg     pgtype.Numeric     `db:"volume_kg" json:"volume_kg"`
	Source       string             `db:"source" json:"source"`
	SourceDigest string             `db:"source_digest" json:"source_digest"`
	AvailableAt  pgtype.Timestamptz `db:"available_at" json:"available_at"`
	RevisionNo   int32              `db:"revision_no" json:"revision_no"`
}

// 同上，但涵蓋一個大類底下的所有子品項（market_code 傳空字串代表不過濾，
// 語意與 GroupObservationsAsOf 一致：每個市場各自的最新觀測，不合併）。
// cutoff 語意同 ObservedPriceByCrop 上方的說明（point-in-time，呼叫端傳
// now，不是 to——review Finding I1）。source/source_digest/available_at/
// revision_no 的新增理由同 ObservedPriceByCrop 上方註解。
func (q *Queries) ObservedPriceByGroup(ctx context.Context, arg ObservedPriceByGroupParams) ([]ObservedPriceByGroupRow, error) {
	rows, err := q.db.Query(ctx, observedPriceByGroup,
		arg.GroupCode,
		arg.MarketCode,
		arg.FromDate,
		arg.ToDate,
		arg.Cutoff,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ObservedPriceByGroupRow{}
	for rows.Next() {
		var i ObservedPriceByGroupRow
		if err := rows.Scan(
			&i.MarketCode,
			&i.CropCode,
			&i.CategoryCode,
			&i.TradeDate,
			&i.AvgPrice,
			&i.UpperPrice,
			&i.MiddlePrice,
			&i.LowerPrice,
			&i.VolumeKg,
			&i.Source,
			&i.SourceDigest,
			&i.AvailableAt,
			&i.RevisionNo,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertCrop = `-- name: UpsertCrop :one
INSERT INTO crop (id, crop_code, group_id, name, variant_name, category_code)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (crop_code) DO UPDATE
  SET name = EXCLUDED.name, group_id = EXCLUDED.group_id,
      variant_name = EXCLUDED.variant_name, category_code = EXCLUDED.category_code,
      updated_at = now()
RETURNING id
`

type UpsertCropParams struct {
	ID           int64   `db:"id" json:"id"`
	CropCode     string  `db:"crop_code" json:"crop_code"`
	GroupID      int64   `db:"group_id" json:"group_id"`
	Name         string  `db:"name" json:"name"`
	VariantName  *string `db:"variant_name" json:"variant_name"`
	CategoryCode *string `db:"category_code" json:"category_code"`
}

func (q *Queries) UpsertCrop(ctx context.Context, arg UpsertCropParams) (int64, error) {
	row := q.db.QueryRow(ctx, upsertCrop,
		arg.ID,
		arg.CropCode,
		arg.GroupID,
		arg.Name,
		arg.VariantName,
		arg.CategoryCode,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}

